/bin/bash -lc "cd [workspace path] && python3 -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb'].astype(int)

def pink_mask(f):
    r,g,b = f[...,0],f[...,1],f[...,2]
    return (r>180)&(r-g>25)&(r-b>35)&(g-b>-10)

for i in [0,9,17,26,35,43,52,60,69,78,86,95]:
    m = pink_mask(d[i])
    ys,xs = np.where(m)
    if len(xs):
        print(i, 'pink count', len(xs), 'x', xs.min(), xs.max(), 'y', ys.min(), ys.max(), 'cx', round(xs.mean(),1), 'cy', round(ys.mean(),1))
    else:
        print(i, 'none')
\""
